import { createRouter, createWebHistory } from "vue-router";
import { auth } from "../firebase/config";

import LoginView from "../views/LoginView.vue";
import RegisterView from "../views/RegisterView.vue";
import DashboardView from "../views/DashboardView.vue";
import ProductsView from "../views/ProductsView.vue";
import AdminPanelView from "../views/AdminPanelView.vue";

const routes = [
  { 
    path: "/", 
    component: DashboardView 
    // Sin meta: requiresAuth para que sea accesible para todos
  },
  { path: "/login", component: LoginView },
  { path: "/registro", component: RegisterView },
  { 
    path: "/productos", 
    component: ProductsView, 
    meta: { requiresAuth: true } 
  },
  { 
    path: "/admin", 
    component: AdminPanelView, 
    meta: { 
      requiresAuth: true,
      requiresAdmin: true 
    } 
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

// Protección global de rutas
router.beforeEach(async (to, from, next) => {
  const user = auth.currentUser;
  
  if (to.meta.requiresAuth && !user) {
    // Si la ruta requiere autenticación y no hay usuario
    next("/login");
  } else if (to.meta.requiresAdmin) {
    // Si la ruta requiere privilegios de admin
    if (!user) {
      next("/login");
    } else {
      // Aquí deberías verificar si el usuario es admin
      // Por ejemplo, verificando un campo en el perfil del usuario
      const isAdmin = user.email === "admin@nexuslibrary.com"; // Ejemplo simple
      if (!isAdmin) {
        next("/"); // Redirige a home si no es admin
      } else {
        next();
      }
    }
  } else {
    next();
  }
});




export default router;
